// Package limits breaks each limit of GO-4 once, so TestGO4 proves that golangci-lint detects it: Branchy is above
// 15 cyclomatic, Nested above 20 cognitive, and this file is above 400 lines.
package limits

// Branchy has a cyclomatic complexity of 16, one plus one per case, and a cognitive complexity of 1 (GO-4).
func Branchy(n int) string {
	switch n {
	case 1:
		return "a"
	case 2:
		return "b"
	case 3:
		return "c"
	case 4:
		return "d"
	case 5:
		return "e"
	case 6:
		return "f"
	case 7:
		return "g"
	case 8:
		return "h"
	case 9:
		return "i"
	case 10:
		return "j"
	case 11:
		return "k"
	case 12:
		return "l"
	case 13:
		return "m"
	case 14:
		return "n"
	case 15:
		return "o"
	}
	return ""
}

// Nested has a cognitive complexity of 21, six ifs each nested in the one before (1+2+3+4+5+6), and a cyclomatic
// complexity of 7 (GO-4).
func Nested(a, b, c, d, e, f bool) int {
	if a {
		if b {
			if c {
				if d {
					if e {
						if f {
							return 1
						}
					}
				}
			}
		}
	}
	return 0
}

